import type { CompletionSource } from '@codemirror/autocomplete';
import {
  CompletionContext,
  autocompletion,
  startCompletion,
} from '@codemirror/autocomplete';
import { syntaxTree } from '@codemirror/language';
import type { Extension } from '@codemirror/state';
import { EditorView } from '@codemirror/view';

import type { _NumberFormatParser } from '../../../core/hooks/useParseNumber.js';
import type { OverlayTriggerState } from '../../../overlays/hooks/useOverlay.js';
import type {
  FilterFieldSuggestions,
  FilterFieldSuggestionsCallback,
} from '../FilterField.js';
import {
  defaultComparisonOperatorSuggestions,
  defaultLogicalOperatorSuggestions,
  defaultValueOperatorSuggestions,
} from '../language/filterfield-language.js';
import {
  convertLezerTree,
  getFilterStatementForSuggestions,
  isFilterFieldLeafNode,
} from '../utils/tree-conversion.js';
import type {
  FilterFieldLeafNode,
  FilterFieldLezerNodeType,
  FilterFieldStatementNode,
} from '../utils/tree-conversion.js';

/** @internal */
export type _FilterFieldSuggestionsContext = {
  token: FilterFieldLeafNode;
  currentStatement: FilterFieldStatementNode | undefined;
};

/** @internal */
export type _FilterFieldSuggestionsCallback = (
  args: [_FilterFieldSuggestionsContext, boolean, boolean, boolean],
) => void;

type SuggestionsExtensionProps = {
  overlayState: OverlayTriggerState;
  numberParser: _NumberFormatParser;
  /**
   * Internal callback that is triggered whenever suggestions may need to be updated.
   * Used to update flags to determine which suggestions to show in the suggestions
   * overlay and update the suggestions context.
   */
  _onSuggest: _FilterFieldSuggestionsCallback;
  /** Consumer callback triggered whenever suggestions may need to be updated. */
  onSuggest?: FilterFieldSuggestionsCallback;
};

export const suggestionsExtension = ({
  overlayState,
  numberParser,
  onSuggest,
  _onSuggest,
}: SuggestionsExtensionProps): Extension => {
  const filterFieldSuggestion: CompletionSource = (
    context: CompletionContext,
  ) => {
    const tree = syntaxTree(context.state);
    const { tree: convertedTree } = convertLezerTree(
      tree,
      numberParser,
      context.state.doc,
    );

    // context.pos returns the first position it finds if a selection is present, which may be the anchor.
    // We always want the cursor position, represented by the selection head.
    const { head: cursorPosition } = context.state.selection.main;
    const currentStatement = getFilterStatementForSuggestions(
      tree,
      cursorPosition,
      numberParser,
      context.state.doc,
    );

    const fallbackToken: FilterFieldLeafNode = {
      type: 'String',
      textValue: '',
      value: '',
      range: {
        from: cursorPosition,
        to: cursorPosition,
      },
    };

    let currentToken: FilterFieldLeafNode;
    if (!currentStatement) {
      currentToken = fallbackToken;
    } else {
      currentToken =
        (Object.values(currentStatement).find(
          (token) =>
            isFilterFieldLeafNode(token) &&
            token.range.from <= cursorPosition &&
            token.range.to >= cursorPosition,
        ) as FilterFieldLeafNode | undefined) ?? fallbackToken;
    }

    let providedSuggestions: FilterFieldSuggestions = [];
    let showLogicalOperators = false;
    let showComparisonOperators = false;
    let showValueOperators = false;
    let suggestionType: Exclude<
      Parameters<FilterFieldSuggestionsCallback>[0],
      undefined
    >['suggestionType'] = 'key';

    const treeCursor = tree.cursorAt(cursorPosition, -1);
    // Move to first child ending before cursor position.
    treeCursor.childBefore(cursorPosition);
    const prevNode =
      treeCursor.node.type.is('FilterValue') ||
      treeCursor.node.parent?.type.is('FilterValue')
        ? 'FilterValue'
        : (treeCursor.node.name as FilterFieldLezerNodeType);

    // Depending on the current cursor position and the already defined parts
    // of the filter statement at the cursor position, the provided suggestions
    // and flags for which suggestions to show in the suggestions overlay are
    // set accordingly.
    if (
      currentStatement === undefined &&
      prevNode !== 'LogicalOperator' &&
      context.state.doc.toString().trim() !== ''
    ) {
      // No filter statement at cursor position, but not an empty filter
      // -> show logical operator suggestions.
      providedSuggestions = defaultLogicalOperatorSuggestions;
      showLogicalOperators = true;
    } else if (
      currentToken.type === 'Key' &&
      ((currentStatement?.operator !== undefined &&
        currentStatement.operator.type !== 'Error') ||
        currentStatement?.value !== undefined)
    ) {
      suggestionType = 'key';
    } else if (
      (prevNode === 'FilterKey' && currentToken.type === 'String') ||
      currentToken.type === 'ComparisonOperator'
    ) {
      // Previous node is a filter key and the delimiter is already entered or
      // previous node is a comparison operator -> show comparison operators.
      providedSuggestions = defaultComparisonOperatorSuggestions;
      showComparisonOperators = true;
      suggestionType = 'comparisonOperator';
    } else if (
      (prevNode === 'ComparisonOperator' &&
        (currentStatement?.value === undefined ||
          (currentStatement.value !== undefined &&
            cursorPosition === currentStatement.value.range.from))) ||
      (currentStatement?.key !== undefined &&
        treeCursor.node.parent?.name === 'FilterSimpleValue' &&
        cursorPosition === treeCursor.node.to)
    ) {
      // Previous node is a comparison operator and the filter value is either undefined
      // or the value is defined and the cursor is right before / after the value
      // -> show value operator suggestions (* / ?).
      providedSuggestions = defaultValueOperatorSuggestions;
      showValueOperators = true;
      suggestionType = 'value';
    }

    if (
      (prevNode === 'ComparisonOperator' &&
        cursorPosition >= treeCursor.node.to &&
        (currentStatement?.operator?.range.to ?? 0) <
          (currentStatement?.value?.range.from ?? 0)) ||
      prevNode === 'FilterValue'
    ) {
      suggestionType = 'value';

      // Do not show value suggestions when a position operator is already present.
      // The tree navigation is a bit weird here, but there doesn't seem to be a way around it.
      const treeCursorClone = treeCursor.node.cursor();
      if (
        treeCursor.node.name === 'PositionOperator' ||
        (treeCursor.prevSibling() &&
          treeCursor.node.name === 'PositionOperator') ||
        (treeCursorClone.nextSibling() &&
          treeCursorClone.firstChild() &&
          treeCursorClone.node.name === 'PositionOperator')
      ) {
        suggestionType = 'none';
      }
    }

    if (prevNode === 'ExistsOperator' || prevNode === 'PositionOperator') {
      suggestionType = 'none';
    }

    _onSuggest([
      { token: currentToken, currentStatement },
      showLogicalOperators,
      showComparisonOperators,
      showValueOperators,
    ]);

    onSuggest?.({
      suggestionType,
      currentToken,
      value: context.state.doc.toString(),
      autoSuggestions: providedSuggestions,
      syntaxTree: convertedTree,
      cursorPosition,
      currentStatement,
    });

    // Open the suggestions overlay only after the callbacks have been called.
    // Else, previous suggestions may still be rendered in the overlay and flicker
    // when updated in the most recent call to 'onSuggest'.
    overlayState.open();

    // Return empty suggestions array to avoid opening codemirror's suggestions overlay.
    return {
      from: currentToken.range.from,
      options: [],
    };
  };

  return [
    autocompletion({ override: [filterFieldSuggestion] }),
    EditorView.updateListener.of((update) => {
      // Trigger autocompletion to call the `onAutocomplete` callback and open the
      // suggestions overlay.
      if (
        (update.focusChanged && update.view.hasFocus) ||
        update.transactions.some(
          (transaction) =>
            transaction.isUserEvent('input') ||
            transaction.isUserEvent('suggestion.apply') ||
            transaction.isUserEvent('delete') ||
            transaction.selection !== undefined,
        )
      ) {
        startCompletion(update.view);
        return;
      }

      if (update.focusChanged && !update.view.hasFocus) {
        overlayState.close();
        return;
      }
    }),
  ];
};
